# We'll try to construct a bipartite graph (which is 2-colorable, hence 4-colorable)
# with girth >= 8 and at least 20 edges.

# Split vertices into two parts
part_a = list(range(8))
part_b = list(range(8, 16))

# Create boolean variables for each possible edge
edges = {}
for u in part_a:
    for v in part_b:
        edges[(u, v)] = Bool(f"e_{u}_{v}")

edge_list = list(edges.keys())

solver = Optimize()

# At least 20 edges
solver.add(Sum([If(edges[e], 1, 0) for e in edge_list]) >= 20)

# Girth >= 8 means no cycles of length 4 or 6
# For bipartite graphs, all cycles are even length
# No 4-cycles: for any two vertices in part_a, they can share at most 1 neighbor in part_b
for u1 in part_a:
    for u2 in part_a:
        if u1 < u2:
            for v1 in part_b:
                for v2 in part_b:
                    if v1 < v2:
                        # No 4-cycle: not all four edges present
                        solver.add(Not(And(edges[(u1, v1)], edges[(u1, v2)], 
                                          edges[(u2, v1)], edges[(u2, v2)])))

# No 6-cycles: for any three vertices in part_a and three in part_b,
# not all 6 edges of a 6-cycle are present
# A 6-cycle in bipartite graph: u1-v1-u2-v2-u3-v3-u1
for u1 in part_a:
    for u2 in part_a:
        for u3 in part_a:
