                                                  edges[(u3, v2)], edges[(u3, v3)])))
                                # u1-v2-u2-v1-u3-v3-u1
                                solver.add(Not(And(edges[(u1, v2)], edges[(u1, v3)],
                                                  edges[(u2, v1)], edges[(u2, v2)],
