def has_4cycle(edges, n):
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # For bipartite graph, check if any two vertices in same part share 2+ neighbors
    for u1 in range(n):
        for u2 in range(u1+1, n):
            common = adj[u1] & adj[u2]
            if len(common) >= 2:
                return True
    return False

